package main

import "fmt"

func averageOfThree(a, b, c int) float64 {
	return float64(a+b+c) / 3
}

func main() {
	var a, b, c int
	fmt.Scan(&a, &b, &c)
	fmt.Printf("%.2f\n", averageOfThree(a, b, c))
}
